CREATE EXTENSION IF NOT EXISTS pgcrypto;

CREATE TYPE user_role AS ENUM ('USER', 'ADMIN');
CREATE TYPE entity_status AS ENUM ('ACTIVE', 'INACTIVE');
CREATE TYPE order_status AS ENUM ('PENDING', 'CONFIRMED', 'SHIPPING', 'COMPLETED', 'CANCELLED', 'REFUNDED');
CREATE TYPE payment_status AS ENUM ('PENDING', 'PAID', 'FAILED', 'REFUNDED');
CREATE TYPE payment_method AS ENUM ('COD', 'BANK_TRANSFER', 'VNPAY', 'MOMO');
CREATE TYPE promo_type AS ENUM ('PERCENT', 'AMOUNT');
CREATE TYPE review_status AS ENUM ('PENDING', 'PUBLISHED', 'HIDDEN');
CREATE TYPE post_status AS ENUM ('DRAFT', 'PUBLISHED');

CREATE TABLE users (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, public_id UUID NOT NULL UNIQUE DEFAULT gen_random_uuid(), email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, full_name VARCHAR(120), phone VARCHAR(20), role user_role NOT NULL DEFAULT 'USER', status entity_status NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ, deleted_at TIMESTAMPTZ);
CREATE TABLE refresh_tokens (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, public_id UUID NOT NULL UNIQUE DEFAULT gen_random_uuid(), user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash VARCHAR(64) NOT NULL UNIQUE, token_family_id UUID NOT NULL, expires_at TIMESTAMPTZ NOT NULL, revoked_at TIMESTAMPTZ, replaced_by_token_id BIGINT UNIQUE REFERENCES refresh_tokens(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), last_used_at TIMESTAMPTZ);
CREATE INDEX ix_refresh_tokens_user_expires ON refresh_tokens(user_id, expires_at); CREATE INDEX ix_refresh_tokens_family ON refresh_tokens(token_family_id);
CREATE TABLE addresses (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, public_id UUID NOT NULL UNIQUE DEFAULT gen_random_uuid(), user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, receiver_name VARCHAR(120) NOT NULL, receiver_phone VARCHAR(20) NOT NULL, line VARCHAR(255) NOT NULL, ward VARCHAR(120), district VARCHAR(120), city VARCHAR(120) NOT NULL, is_default BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE categories (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, public_id UUID NOT NULL UNIQUE DEFAULT gen_random_uuid(), parent_id BIGINT REFERENCES categories(id) ON DELETE RESTRICT, name VARCHAR(120) NOT NULL, slug VARCHAR(150) NOT NULL UNIQUE, image_url VARCHAR(255), meta_title VARCHAR(160), meta_description VARCHAR(255), status entity_status NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), deleted_at TIMESTAMPTZ);
CREATE TABLE brands (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, public_id UUID NOT NULL UNIQUE DEFAULT gen_random_uuid(), name VARCHAR(120) NOT NULL, slug VARCHAR(150) NOT NULL UNIQUE, logo_url VARCHAR(255), info TEXT, meta_title VARCHAR(160), meta_description VARCHAR(255), status entity_status NOT NULL DEFAULT 'ACTIVE', deleted_at TIMESTAMPTZ);
CREATE TABLE products (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, public_id UUID NOT NULL UNIQUE DEFAULT gen_random_uuid(), category_id BIGINT NOT NULL REFERENCES categories(id) ON DELETE RESTRICT, brand_id BIGINT NOT NULL REFERENCES brands(id) ON DELETE RESTRICT, name VARCHAR(200) NOT NULL, slug VARCHAR(220) NOT NULL UNIQUE, description TEXT, min_price NUMERIC(12,2), thumbnail_url VARCHAR(255), rating_avg NUMERIC(2,1) DEFAULT 0, review_count INTEGER NOT NULL DEFAULT 0, warranty_months INTEGER DEFAULT 0, meta_title VARCHAR(160), meta_description VARCHAR(255), og_image VARCHAR(255), gender VARCHAR(32), has_lens BOOLEAN NOT NULL DEFAULT FALSE, face_tags VARCHAR(32)[] NOT NULL DEFAULT '{}', status entity_status NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ, deleted_at TIMESTAMPTZ);
CREATE TABLE product_variants (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, public_id UUID NOT NULL UNIQUE DEFAULT gen_random_uuid(), product_id BIGINT NOT NULL REFERENCES products(id) ON DELETE CASCADE, sku VARCHAR(64) NOT NULL UNIQUE, color VARCHAR(60), size VARCHAR(30), material VARCHAR(60), lens_option VARCHAR(60), price NUMERIC(12,2) NOT NULL CHECK (price >= 0), stock_qty INTEGER NOT NULL DEFAULT 0 CHECK (stock_qty >= 0), version INTEGER NOT NULL DEFAULT 0, deleted_at TIMESTAMPTZ);
CREATE TABLE product_images (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, public_id UUID NOT NULL UNIQUE DEFAULT gen_random_uuid(), product_id BIGINT NOT NULL REFERENCES products(id) ON DELETE CASCADE, url VARCHAR(255) NOT NULL, alt VARCHAR(160), sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE carts (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, public_id UUID NOT NULL UNIQUE DEFAULT gen_random_uuid(), user_id BIGINT NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE, updated_at TIMESTAMPTZ);
CREATE TABLE cart_items (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, public_id UUID NOT NULL UNIQUE DEFAULT gen_random_uuid(), cart_id BIGINT NOT NULL REFERENCES carts(id) ON DELETE CASCADE, variant_id BIGINT NOT NULL REFERENCES product_variants(id) ON DELETE RESTRICT, quantity INTEGER NOT NULL DEFAULT 1 CHECK (quantity > 0), UNIQUE(cart_id, variant_id));
CREATE TABLE promotions (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, public_id UUID NOT NULL UNIQUE DEFAULT gen_random_uuid(), code VARCHAR(40) NOT NULL UNIQUE, name VARCHAR(150), type promo_type NOT NULL, value NUMERIC(12,2) NOT NULL, min_value NUMERIC(12,2) DEFAULT 0, usage_limit INTEGER, used_count INTEGER NOT NULL DEFAULT 0, start_at TIMESTAMPTZ, end_at TIMESTAMPTZ, status entity_status NOT NULL DEFAULT 'ACTIVE');
CREATE TABLE orders (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, public_id UUID NOT NULL UNIQUE DEFAULT gen_random_uuid(), user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, order_code VARCHAR(30) NOT NULL UNIQUE, promotion_id BIGINT REFERENCES promotions(id) ON DELETE SET NULL, subtotal NUMERIC(12,2) NOT NULL, discount_amount NUMERIC(12,2) NOT NULL DEFAULT 0, shipping_fee NUMERIC(12,2) NOT NULL DEFAULT 0, total NUMERIC(12,2) NOT NULL, shipping_address VARCHAR(500) NOT NULL, receiver_name VARCHAR(120), receiver_phone VARCHAR(20), tracking_code VARCHAR(60), status order_status NOT NULL DEFAULT 'PENDING', note VARCHAR(500), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ, version INTEGER NOT NULL DEFAULT 0);
CREATE TABLE order_items (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, public_id UUID NOT NULL UNIQUE DEFAULT gen_random_uuid(), order_id BIGINT NOT NULL REFERENCES orders(id) ON DELETE CASCADE, variant_id BIGINT NOT NULL REFERENCES product_variants(id) ON DELETE RESTRICT, product_name VARCHAR(200) NOT NULL, sku VARCHAR(64), unit_price NUMERIC(12,2) NOT NULL, quantity INTEGER NOT NULL CHECK (quantity > 0), line_total NUMERIC(12,2) NOT NULL);
CREATE TABLE payments (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, public_id UUID NOT NULL UNIQUE DEFAULT gen_random_uuid(), order_id BIGINT NOT NULL REFERENCES orders(id) ON DELETE RESTRICT, method payment_method NOT NULL, amount NUMERIC(12,2) NOT NULL, status payment_status NOT NULL DEFAULT 'PENDING', payment_ref VARCHAR(120), paid_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE reviews (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, public_id UUID NOT NULL UNIQUE DEFAULT gen_random_uuid(), user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, product_id BIGINT NOT NULL REFERENCES products(id) ON DELETE RESTRICT, order_id BIGINT REFERENCES orders(id) ON DELETE SET NULL, rating SMALLINT NOT NULL CHECK (rating BETWEEN 1 AND 5), content TEXT, status review_status NOT NULL DEFAULT 'PENDING', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE wishlists (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, public_id UUID NOT NULL UNIQUE DEFAULT gen_random_uuid(), user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, product_id BIGINT NOT NULL REFERENCES products(id) ON DELETE CASCADE, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(user_id, product_id));
CREATE TABLE blog_posts (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, public_id UUID NOT NULL UNIQUE DEFAULT gen_random_uuid(), author_id BIGINT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, title VARCHAR(200) NOT NULL, slug VARCHAR(220) NOT NULL UNIQUE, excerpt VARCHAR(300), content TEXT, cover_image VARCHAR(255), meta_title VARCHAR(160), meta_description VARCHAR(255), status post_status NOT NULL DEFAULT 'DRAFT', published_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE notifications (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, public_id UUID NOT NULL UNIQUE DEFAULT gen_random_uuid(), user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, title VARCHAR(160), body VARCHAR(500), type VARCHAR(40), is_read BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE url_redirects (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, public_id UUID NOT NULL UNIQUE DEFAULT gen_random_uuid(), old_path VARCHAR(255) NOT NULL UNIQUE, new_path VARCHAR(255) NOT NULL, status INTEGER NOT NULL DEFAULT 301, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX ix_categories_parent ON categories(parent_id); CREATE INDEX ix_products_category ON products(category_id); CREATE INDEX ix_products_brand ON products(brand_id); CREATE INDEX ix_products_status_created ON products(status, created_at DESC); CREATE INDEX ix_products_status_price ON products(status, min_price); CREATE INDEX ix_products_face_tags ON products USING GIN(face_tags); CREATE INDEX ix_products_search ON products USING GIN(to_tsvector('simple', name || ' ' || coalesce(description, ''))); CREATE INDEX ix_variants_product ON product_variants(product_id); CREATE INDEX ix_images_product ON product_images(product_id); CREATE INDEX ix_orders_user_status_created ON orders(user_id, status, created_at DESC); CREATE INDEX ix_order_items_order ON order_items(order_id); CREATE INDEX ix_order_items_variant ON order_items(variant_id); CREATE INDEX ix_reviews_product ON reviews(product_id); CREATE INDEX ix_reviews_user ON reviews(user_id);
